mapper.select:
SELECT a.msg_id AS id, a.ref_msg_id AS ref_id, a.transaction_id, a.context_id, a.plan_id, a.msg_type AS type, a.role, b.msg_text AS content, a.like_type, a.begin_time, a.end_time, b.ext_params FROM bt_bot_session_msg a JOIN bt_bot_session_msg_text b ON a.msg_id = b.msg_id WHERE a.status_cd = '00A' AND a.session_id = #{sessionId}
AND a.msg_type NOT IN ('point', 'questions', 'exception')
AND b.msg_text IS NOT NULL ORDER BY a.sort

SELECT transaction_id
FROM (
    SELECT transaction_id, MAX(sort) AS sort
    FROM bt_bot_session_msg
    WHERE status_cd = '00A'
      AND session_id = #{query.sessionId}

      AND (context_id IS NULL OR context_id NOT LIKE 'sub:%')

      AND msg_type NOT IN ('point', 'pageFunc', 'questions', 'exception')
      AND (plan_id IS NULL OR msg_type = 'confirmPlan')

      AND sort < #{query.lastMsgSort}


      AND scene_id = #{query.sceneId}


      AND like_type = #{query.likeType}


      AND like_type IS NULL

    GROUP BY transaction_id
) tmp
ORDER BY sort

SELECT a.msg_id AS id, a.ref_msg_id AS ref_id, a.bot_id, a.transaction_id, a.context_id, a.scene_id, a.plan_id, a.msg_type AS type, a.role, b.msg_text AS content, b.download_type, b.content_type, b.paragraph_group, b.paragraph_sortby, a.like_type, a.begin_time, a.end_time, b.ext_params, a.sort FROM bt_bot_session_msg a LEFT JOIN bt_bot_session_msg_text b ON a.msg_id = b.msg_id WHERE a.status_cd = '00A' AND a.session_id = #{sessionId}
AND a.msg_type NOT IN ('point', 'pageFunc', 'questions', 'exception')
AND b.msg_text IS NOT NULL AND a.ref_msg_id IN (#{msgId})

SELECT a.msg_id AS id, a.ref_msg_id AS ref_id, a.bot_id, a.transaction_id, a.context_id, a.scene_id, a.plan_id, a.msg_type AS type, a.role, b.msg_text AS content, b.download_type, b.content_type, b.paragraph_group, b.paragraph_sortby, a.like_type, a.begin_time, a.end_time, b.ext_params, a.sort FROM bt_bot_session_msg a JOIN bt_bot_session_msg_text b ON a.msg_id = b.msg_id WHERE a.status_cd = '00A' AND a.session_id = #{sessionId}
AND a.msg_type NOT IN ('point', 'questions', 'exception')
AND b.msg_text IS NOT NULL AND a.plan_id IN (#{planId}) ORDER BY a.sort DESC

SELECT a.msg_id, a.msg_type, c.msg_text, a.begin_time, a.session_id, a.msg_status,
b.bot_id, f.bot_name, b.bot_tenant_id,
a.scene_id, e.scene_name, e.scene_type,
b.creator_id AS user_id, d.real_name AS user_name, d.user_name AS user_code
FROM bt_bot_session_msg a
JOIN bt_bot_session b ON b.session_id = a.session_id
JOIN bt_bot_session_msg_text c ON c.msg_id = a.msg_id
LEFT JOIN bt_user d ON d.user_id = b.creator_id
LEFT JOIN bt_bot_scene e ON e.scene_id = a.scene_id AND e.tenant_id = b.bot_tenant_id
LEFT JOIN bt_bot f ON b.bot_id = f.bot_id AND f.tenant_id IN (-1, b.bot_tenant_id)
WHERE a.status_cd = '00A'
  AND (b.tenant_id = #{query.tenantId} OR b.space_id = #{query.tenantId})
  AND (a.msg_type IN ('input', 'point') OR (a.msg_type IN ('general', 'a2ui') AND a.role = 'user'))

  AND b.bot_id = #{query.botId}


  AND a.scene_id = #{query.sceneId}


  AND b.creator_id = #{query.userId}


  AND a.begin_time >= #{query.minBeginTime}


  AND a.begin_time <= #{query.maxBeginTime}


  AND a.msg_type = #{query.msgType}


  AND a.msg_status = #{query.msgStatus}



  AND c.msg_text IS NOT NULL
  AND c.msg_text LIKE #{query.keyword}

ORDER BY a.begin_time DESC

SELECT MAX(a.sort) FROM bt_bot_session_msg a WHERE a.session_id = #{sessionId} AND a.status_cd = '00A'
AND a.context_id IS NULL
AND a.context_id = #{contextId}

SELECT a.msg_type, a.role AS msg_role, b.msg_text
FROM bt_bot_session_msg a
       JOIN bt_bot_session_msg_text b ON a.msg_id = b.msg_id
WHERE a.status_cd = '00A'
  AND a.session_id = #{sessionId}
  AND a.context_id = #{contextId}
  AND a.begin_time > #{date}
  AND a.msg_type IN ('input', 'text')
  AND b.msg_text IS NOT NULL
ORDER BY a.begin_time

SELECT * FROM ( SELECT a.msg_id, a.session_id, a.transaction_id, a.scene_id, a.context_id, a.sort FROM bt_bot_session_msg a WHERE a.status_cd = '00A' AND a.session_id = #{sessionId}
AND a.context_id = #{contextId}
ORDER BY a.sort DESC, a.created_time DESC) TMP WHERE 1=1 1

SELECT scene_id
FROM bt_bot_session_msg
WHERE status_cd = '00A'
  AND session_id = #{sessionId}
  AND context_id = #{contextId}
 1

